508	            Tensor tCrAi_k = make_fragment_like<BF16>(thr_mma.partition_fragment_A(A_ref));
509	            auto tCrAi_k_view = smem_thr_copy_A.retile_D(tCrAi_k);
510	            auto tCrA_k = thr_mma.partition_fragment_A(A_ref);
511	
512	            Tensor tCrAi_q = make_fragment_like<BF16>(thr_mma.partition_fragment_A(A_ref));
513	            auto tCrAi_q_view = smem_thr_copy_A.retile_D(tCrAi_q);
514	            auto tCrA_q = thr_mma.partition_fragment_A(A_ref);
515	
516	            Tensor tCrBi = make_fragment_like<BF16>(thr_mma.partition_fragment_B(B_ref));
517	            auto tCrBi_view = smem_thr_copy_B.retile_D(tCrBi);
518	            auto tCrB = thr_mma.partition_fragment_B(B_ref);
519	
520	            auto tCrC_ref = thr_mma.partition_C(C_ref);
521	
522	            using AccFragT = decltype(thr_mma.make_fragment_C(tCrC_ref));
523	            using SFragT = decltype(make_fragment_like<BF16>(thr_mma.make_fragment_C(tCrC_ref)));
524	            using AFragT = decltype(thr_mma.partition_fragment_A(A_ref));
525	            using BFragT_u = decltype(thr_mma.partition_fragment_B(B_ref));
526	
527	            AccFragT u_acc[2], out_acc[2];
528	            #pragma unroll
529	            for (int i = 0; i < 2; ++i) { u_acc[i] = thr_mma.make_fragment_C(tCrC_ref); clear(u_acc[i]); }
530	            #pragma unroll
531	            for (int i = 0; i < 2; ++i) { out_acc[i] = thr_mma.make_fragment_C(tCrC_ref); clear(out_acc[i]); }
532	
533	            // ======== Phase 1: Dual GEMM k@s and q@s (k-loop, 2 blocks per warp) ========
534	            constexpr int K_BLOCKS = decltype(cute::size<1>(k_decayed))::value / 16;
535	
536	            copy(smem_tiled_copy_A, smem_thr_copy_A.partition_S(
537	                local_tile(k_decayed, make_shape(Int<16>{}, Int<16>{}), make_coord(0, 0))), tCrAi_k_view);
538	            copy(smem_tiled_copy_A, smem_thr_copy_A.partition_S(
