639	                tCrB_u_arr[i] = thr_mma.partition_fragment_B(B_ref);
640	                uint32_t* b_dst = reinterpret_cast<uint32_t*>(&tCrB_u_arr[i](0));
641	                b_dst[0] = u_b_regs[0]; b_dst[1] = u_b_regs[1];
642	                b_dst[2] = u_b_regs[2]; b_dst[3] = u_b_regs[3];
643	
644	                clear(out_acc[i]);
645	                gemm(thr_mma, tCrA_k(_,_,Int<0>{}), tCrB_u_arr[i](_,_,Int<0>{}), out_acc[i]);
