765	                    }
766	                }
767	            } else {
768	                // TMA store for full tiles
769	                auto out_off = g_out.layout()(head_idx, int(bos) + t * CHUNK, 0);
770	                Tensor g_out_tile = make_tensor(g_out.data() + out_off,
771	                    make_layout(make_shape(Int<1>{}, Int<CHUNK>{}, Int<D>{}), stride(g_out.layout())));
772	                Tensor s_out_tile = make_tensor(make_smem_ptr(out_stage_ptr), TMAVOLayout{});
773	                cute::copy(
774	                    tma_store_out,
775	                    cta_tma_store.partition_S(s_out_tile),
776	                    cta_tma_store.partition_D(g_out_tile)
777	                );
778	                tma_store_arrive();
779	            }
780	
781	            tma_store_wait<0>();
782	            store_pipeline.consumer_release(out_read);
783	            ++out_read;
784	        }
785	
786	        if constexpr (HasStateOut && !StateFP32) {
787	            // BF16 state: TMA store directly from state_acc
788	            Tensor g_final = tma_store_final_state.get_tma_tensor(make_shape(N * H, D, D));
789	            auto state_off = g_final.layout()(seq_idx * H + head_idx, 0, 0);
790	            Tensor g_final_tile = make_tensor(g_final.data() + state_off,
791	                make_layout(make_shape(Int<1>{}, Int<D>{}, Int<D>{}), stride(g_final.layout())));
792	            Tensor s_state = make_tensor(make_smem_ptr(shared_storage.state_acc.begin()), TMAStateSmemLayout{});
793	
794	            auto cta_tma_store_state = tma_store_final_state.get_slice(Int<0>{});
795	            cute::copy(
796	                tma_store_final_state,
797	                cta_tma_store_state.partition_S(s_state),
798	                cta_tma_store_state.partition_D(g_final_tile)
799	            );
800	            tma_store_arrive();
801	        }
802	    }
803	
804	    if constexpr (HasStateOut && StateFP32) {
805	        // FP32 state: all threads sync, convert bf16->fp32, then STORE warp does TMA
806	        using FP32StateSmemLayout = typename Layouts::FP32StateSmemLayout;
807	        using TMAFP32StateSmemLayout = typename Layouts::TMAFP32StateSmemLayout;
808	
809	        __syncthreads();  // all warps sync — pipeline smem now free
810	
811	        smem_cvt_bf16_to_fp32<StateSmemLayout, FP32StateSmemLayout, D, NumThreads>(
812	            shared_storage.state_acc.begin(),
813	            reinterpret_cast<float*>(shared_storage.state_fp32_buf),
814	            threadIdx.x);
815	        cutlass::arch::fence_view_async_shared();  // generic-proxy writes -> visible to async proxy (TMA)
816	        __syncthreads();  // conversion complete
817	
818	        if (warp_role == WarpRole::STORE && lane_predicate) {
819	            Tensor g_final = tma_store_final_state.get_tma_tensor(make_shape(N * H, D, D));
820	            auto state_off = g_final.layout()(seq_idx * H + head_idx, 0, 0);
821	            Tensor g_final_tile = make_tensor(g_final.data() + state_off,
822	                make_layout(make_shape(Int<1>{}, Int<D>{}, Int<D>{}), stride(g_final.layout())));
823	            Tensor s_fp32 = make_tensor(
824	                make_smem_ptr(reinterpret_cast<float*>(shared_storage.state_fp32_buf)),
825	                TMAFP32StateSmemLayout{});
826	
827	            auto cta_tma_store_state = tma_store_final_state.get_slice(Int<0>{});
828	            cute::copy(
829	                tma_store_final_state,
830	                cta_tma_store_state.partition_S(s_fp32),
831	                cta_tma_store_state.partition_D(g_final_tile)
832	            );
833	            tma_store_arrive();
834	        }
835	    }
836	
837	    __syncthreads();
838	#endif
839	}
